#include "KS/SRC/entity_anim_shared.h"

class ett_manager {
public:
    void release(const entity_track_tree *track);
};

class world_dynamics_system {
public:
    ett_manager *get_ett_manager();
};

extern world_dynamics_system *g_world_ptr;

entity_anim_tree::~entity_anim_tree()
{
    clear_anims();

    clear_anims_b();

    detach();

    if (track)
    {
        g_world_ptr->get_ett_manager()->release(track);
        track = 0;
    }

    if (trackb)
    {
        g_world_ptr->get_ett_manager()->release(trackb);
        trackb = 0;
    }
}
